fn gcd(a: Int, b: Int) -> Int {
    while b != 0 {
        let r = a % b
        a = b
        b = r
    }
    a
}

fn main() {
    print(gcd(252, 105))
}

fn gcd(a: Int, b: Int) -> Int {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn main() {
    print(gcd(252, 105))
}

fn gcd(mut a: u32, mut b: u32) -> u32 {
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

fn main() {
    println!("{}", gcd(252, 105));
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return False
    }
    for i in range(2, n) {
        if n % i == 0 {
            return False
        }
    }
    True
}

